struct Profile {
    // Created on first use, not at init.
    lazy var cache = ImageCache()
}

var firstName = "Mina"
var lastName = "Kim"
// Calculated on every read. Nothing is stored.
var fullName: String {
    "\(firstName) \(lastName)"
}

// Runs right before and right after a change.
var score = 0 {
    willSet { print("new: \(newValue)") }
    didSet { print("old: \(oldValue)") }
}
